function animateTokensPage() {
  const page = document.getElementById('page-tokens');
  if (!page || page.style.display === 'none') return;
  page.classList.remove('tokens-enter');
  void page.offsetWidth;
  page.classList.add('tokens-enter');

  page.querySelectorAll('.token-animate-number').forEach(el => {
    const target = Number(el.dataset.target || 0);
    const kind = el.dataset.kind || 'int';
    const start = performance.now();
    const duration = 850;
    const render = now => {
      const t = Math.min(1, (now - start) / duration);
      const eased = 1 - Math.pow(1 - t, 3);
      const value = target * eased;
      el.textContent = kind === 'cost' ? fmtCost(value) : kind === 'tok' ? fmtTok(value) : String(Math.round(value));
      if (t < 1) requestAnimationFrame(render);
    };
    requestAnimationFrame(render);
  });

  page.querySelectorAll('.token-line-path, .token-total-line').forEach((path, idx) => {
    const len = path.getTotalLength ? path.getTotalLength() : 0;
    if (!len) return;
    path.style.strokeDasharray = len;
    path.style.strokeDashoffset = len;
    path.style.animation = `token-line-draw 900ms ${idx * 70}ms cubic-bezier(.22,.61,.36,1) forwards`;
  });
  page.querySelectorAll('.token-total-area').forEach(area => {
    area.style.opacity = '0';
    area.style.animation = 'token-area-fade 800ms 450ms ease forwards';
  });
  page.querySelectorAll('.routing-pie-slice').forEach((slice, idx) => {
    slice.style.transformOrigin = '100px 100px';
    slice.style.opacity = '0';
    slice.style.animation = `token-pie-in 650ms ${idx * 90}ms cubic-bezier(.22,.61,.36,1) forwards`;
  });
}

